<script setup lang="ts">
import {watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import type {ToolDraft,JsonObject} from '@/domain/types'
const props=defineProps<{draft:ToolDraft;columns:Record<string,string[]>;errors:Record<string,string>;loading:Record<string,boolean>}>()
const modes=[{key:'duplicate',config:'duplicate_detection',label:'重复项目'},{key:'parentChild',config:'parent_child_analysis',label:'主子项目'}]
function ensure(){const c=props.draft.config;c.engineeringMappings||={};for(const f of props.draft.files){const target=(c.engineeringMappings[f.id]||={});for(const mode of modes){if(target[mode.key]?.length)continue;const source=c[mode.config]||{},mapping=source.field_mapping||{};let rows=Object.entries(mapping).map(([key,v])=>{const e=v as JsonObject;return{key,column:e.excel_column||e.column||'',compare_type:e.compare_type||'similarity',threshold:e.threshold??0.8,weight:source.llm_config?.field_weights?.[key]??0,rule:source.llm_config?.field_prompt_rules?.[key]||''}});if(!rows.length&&c.fieldMappings?.[f.id]){rows=Object.entries(c.fieldMappings[f.id]).filter(([,column])=>column).map(([role,column],i,all)=>({key:'F'+(i+1),column:String(column),compare_type:role==='investment'?(mode.key==='duplicate'?'investment_diff':'investment_gt'):'similarity',threshold:0.8,weight:c.weights?.[role]??1/all.length,rule:c.fieldRules?.[role]||source.llm_config?.field_prompt_rules?.['F'+(i+1)]||''}))}target[mode.key]=rows}}}
watch(()=>[props.draft,props.draft.files,props.draft.config.duplicate_detection,props.draft.config.parent_child_analysis],ensure,{immediate:true})
function add(fileId:string,mode:string){const rows=props.draft.config.engineeringMappings[fileId][mode];rows.push({key:'F'+(Math.max(0,...rows.map((r:any)=>Number(r.key.slice(1))))+1),column:'',compare_type:'similarity',threshold:0.8,weight:rows.length?0:1,rule:'按原表内容相似程度评分，0–5 分；缺失信息不推断。'})}
async function remove(fileId:string,mode:string,index:number){const rows=props.draft.config.engineeringMappings[fileId][mode];try{await ElMessageBox.confirm('移除该字段后，本台账中依赖它的判断规则也不再参与分析。请重新确认剩余字段的权重。','移除比较字段',{confirmButtonText:'移除',cancelButtonText:'取消'});rows.splice(index,1)}catch{}}
</script>
<template><section class="form-section"><h3>设置台账比较字段</h3><p class="help">每份台账分别配置，两类分析可使用不同字段。字段权重合计为 1。</p><el-empty v-if="!draft.files.length" :image-size="50" description="添加台账后配置比较字段"/><article v-for="file in draft.files" :key="file.id" class="engineering-file"><h4>{{file.name}}</h4><p v-if="errors[file.id]" class="mapping-error">{{errors[file.id]}}</p><template v-for="mode in modes" :key="mode.key"><section v-if="mode.key==='duplicate'?draft.config.duplicateEnabled:draft.config.parentChildEnabled" class="engineering-mode"><div class="mode-heading"><strong>{{mode.label}}</strong><el-button @click="add(file.id,mode.key)">添加比较字段</el-button><el-button @click="draft.config.engineeringMappings[file.id][mode.key].forEach((r:any)=>r.weight=1/draft.config.engineeringMappings[file.id][mode.key].length)">均分权重</el-button></div><div v-for="(row,i) in draft.config.engineeringMappings?.[file.id]?.[mode.key]||[]" :key="row.key" class="engineering-field"><div class="field-line"><span>{{row.key}}</span><el-select v-model="row.column" filterable :loading="loading[file.id]" placeholder="选择原表字段" :aria-label="file.name+' '+mode.label+'字段 '+(Number(i)+1)"><el-option v-for="col in columns[file.id]" :key="col" :value="col"/></el-select><el-select v-model="row.compare_type" aria-label="比较方式"><el-option label="文本相似度" value="similarity"/><el-option label="金额差异" value="investment_diff"/><el-option v-if="mode.key==='parentChild'" label="主项目金额较大" value="investment_gt"/><el-option label="完全相等" value="exact"/></el-select><el-button text type="danger" @click="remove(file.id,mode.key,Number(i))">移除</el-button></div><div class="field-line"><label>权重</label><el-input-number v-model="row.weight" :min="0" :max="1" :step="0.05"/><label>预筛阈值</label><el-input-number v-model="row.threshold" :min="0" :max="1" :step="0.05"/></div><el-input v-model="row.rule" type="textarea" :rows="2" placeholder="说明如何比较和评分" aria-label="字段评分说明"/></div></section></template></article></section></template>
<style scoped>.engineering-file{margin-top:16px}.engineering-file h4{margin:0 0 10px;font-size:15px}.engineering-mode{border:1px solid #e6ebf1;border-radius:7px;padding:12px;margin:10px 0}.mode-heading{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.mode-heading strong{margin-right:auto}.engineering-field{background:#f8fafc;padding:12px;margin-top:12px;border-radius:5px}.field-line{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:10px}.field-line .el-select{flex:1;min-width:170px}.field-line .el-input-number{width:130px}.mapping-error{color:#a33e3e;font-size:14px}</style>
